{
  "@context": "https://schema.org",
  "@type": "TouristTrip",
  "name": "6-Day Marrakech, Sahara Desert and Fes Tour",
  "description": "A shared, one-way group tour from Marrakech to Fes — arrival and hostel transfer, a crossing of the High Atlas via Ait Benhaddou to the Dades Gorges, a camel trek and overnight desert camp at Merzouga, then two nights in Fes with guided medina sightseeing.",
  "touristType": ["Budget travelers", "Backpackers", "Solo travelers"],
  "itinerary": {
    "@type": "ItemList",
    "itemListElement": [
      { "@type": "ListItem", "position": 1, "item": { "@type": "TouristAttraction", "name": "Day 1: Arrival in Marrakech", "description": "Airport pick-up and transfer to your hostel in the Marrakech medina. Free time to explore Jemaa el-Fnaa and the surrounding souks." } },
      { "@type": "ListItem", "position": 2, "item": { "@type": "TouristAttraction", "name": "Day 2: Marrakech to Dades Gorges", "description": "Cross the High Atlas via the Tizi n'Tichka pass, stop at the UNESCO-listed Ait Benhaddou kasbah, and continue through the Valley of Roses to an overnight stay in the Dades Gorges." } },
      { "@type": "ListItem", "position": 3, "item": { "@type": "TouristAttraction", "name": "Day 3: Dades Gorges to Merzouga Desert", "description": "Drive via Tinghir and Erfoud to Merzouga, gateway to the Sahara, then a camel ride into the Erg Chebbi dunes to reach your desert camp for the night." } },
      { "@type": "ListItem", "position": 4, "item": { "@type": "TouristAttraction", "name": "Day 4: Merzouga to Fes", "description": "Morning camel ride back from the dunes, then a full day's drive north via Er-Rachidia, Midelt and the Middle Atlas to Fes. Overnight in Riad Fez Mahal or La Perle de la Medina." } },
      { "@type": "ListItem", "position": 5, "item": { "@type": "TouristAttraction", "name": "Day 5: Fes sightseeing with a local guide", "description": "Full guided day through the Fes el-Bali medina — the tanneries, souks, and the Bou Inania Madrasa. Overnight in the same Fes riad." } },
      { "@type": "ListItem", "position": 6, "item": { "@type": "TouristAttraction", "name": "Day 6: Transfer to Fes Airport", "description": "Transfer from your Fes riad to Fes-Saïss Airport (FEZ). Trip ends." } }
    ]
  },
  "offers": {
    "@type": "Offer",
    "priceCurrency": "EUR",
    "price": "412",
    "availability": "https://schema.org/InStock"
  },
  "provider": {
    "@type": "TravelAgency",
    "name": "Shared Morocco Adventures",
    "url": "https://www.sharedmoroccoadventures.com"
  }
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    { "@type": "Question", "name": "Is this trip one-way, or does it return to Marrakech?", "acceptedAnswer": { "@type": "Answer", "text": "One-way — you're picked up in Marrakech on Day 1 and dropped off in Fes on Day 6, so there's no long drive back across the Atlas at the end." } },
    { "@type": "Question", "name": "Is accommodation shared?", "acceptedAnswer": { "@type": "Answer", "text": "Yes — the €412 price is based on shared twin/dorm rooms in Marrakech, the Dades Gorges and Fes, and a shared tent at the desert camp. A private room upgrade is available on request for an additional cost." } },
    { "@type": "Question", "name": "What should I pack for the desert night?", "acceptedAnswer": { "@type": "Answer", "text": "Desert nights get cold even in summer — bring a warm layer, plus sunscreen, a scarf or hat for wind and sun, and comfortable walking shoes." } },
    { "@type": "Question", "name": "Is the Fes sightseeing day guided?", "acceptedAnswer": { "@type": "Answer", "text": "Yes — Day 5 includes a full day with a local guide through the Fes el-Bali medina, covering the tanneries, souks and the Bou Inania Madrasa." } },
    { "@type": "Question", "name": "Can I extend this into Chefchaouen and the Middle Atlas?", "acceptedAnswer": { "@type": "Answer", "text": "Yes — see our 8-Day Marrakech, Sahara, Fes &amp; Chefchaouen Tour, which adds a Chefchaouen day trip and a Middle Atlas/Ifrane day trip from Fes before your final departure." } },
    { "@type": "Question", "name": "What if the group doesn't fill up?", "acceptedAnswer": { "@type": "Answer", "text": "Departures run on fixed weekly dates regardless of group size — your trip runs even if only a few seats are booked." } }
  ]
}
